    background-color: transparent!important;
    font-weight: 600;
    text-decoration: none!important;
    text-transform: uppercase;
}

.njt-nofi-button a::after {
    content: url('../img/noti-arrow.svg');
    position: absolute;
    top: 12%;
    right: -25px;
    transition: 300ms;
}

.njt-nofi-notification-bar .njt-nofi-hide .njt-nofi-close-icon {
    background-color: transparent;
}

.njt-nofi-notification-bar .njt-nofi-content {
    justify-content: flex-start!important;
    padding: 15px 17px!important;
    text-align: left!important;
    font-weight: 700;
    max-width: 100%;
}

.njt-nofi-notification-bar .njt-nofi-content .bjt-nofi-text {
    max-width: 90%;
}

@media (min-width: 1024px) {
    .njt-nofi-notification-bar .njt-nofi-content {
        padding: 15px 50px!important;
        text-align: center!important;
        justify-content: center!important;
    }

    .njt-nofi-notification-bar .njt-nofi-content .bjt-nofi-text 	{
        max-width: 100%;
    }
}

@media (max-width: 769px) {
    .njt-nofi-notification-bar .njt-nofi-content .njt-nofi-button a {
        padding: 0;
        font-size: 14px;
    }
}

.njt-nofi-text {
    position: relative;
}

.njt-nofi-text:after {
    display: none;
    content: '';
    width: 15px;
    height: 1px;
    background-color: #ffffff;
    position: absolute;
    right: -12px;
    top: 50%;
    transform: translate

Y(-50%);
}

@media (min-width: 1024px) {
    .njt-nofi-text:after {
        display: block;
    }
}

.njt-nofi-notification-bar .njt-nofi-hide .njt-nofi-close-icon {
    width: 13px;
    height: 13px;
    padding: 0;
}

.njt-nofi-notification-bar .njt-nofi-hide {
    top: 20px;
}

.njt-nofi-container {
    top: 80px!important;
    z-index: 10;
    transition: top ease-in-out 0.5s, opacity ease-in-out 0.5s;
    opacity: 0;
}

.njt-nofi-container.show {
    opacity: 1;
    transition: opacity ease-in-out 0.5s;
}

.njt-nofi-container.notification-hidden {
    top: -115px!important;
    transition: top ease-in-out 0.5s;
}

@media (min-width: 768px) {
    .njt-nofi-container {
        top: 110px!important;
    }

    .njt-nofi-container.notification-hidden {
        top: -61px!important;
        transition: top ease-in-out 0.5s;
    }
}

@media (min-width: 1024px) {
    .njt-nofi-container {
        top: 162px!important;
    }
}

@media (min-width: 1200px) {
    .njt-nofi-container {
        top: 112px!important;
    }
}

.home.page-template,
.page.page-template {
    padding-top: 0!important;
    top: 0!important;
    transition: padding-top ease-in-out 0.5s;
}

