    transform: scale(1);
}

.njt-nofi-notification-bar .njt-nofi-content:hover .njt-nofi-button a::after {
    transform: translateX(12px);
}

.njt-nofi-notification-bar .njt-nofi-content:hover::before {
    opacity: 1;
