@import url('../globals.css');
@import url('../mega-menu/hamburger.css');
@import url('../mega-menu/fontello/css/centric.css');

/* Mega Menu Start */
.home-hero--new-design {
	height: 100vh;
	max-height: 980px;
}
.hamburger {
	left:1vw;
	transition: 300ms;
}
.hamburger-box {
	transition:300ms;
	transform: scale(1);
}
.hamburger:not(.is-active):hover {
	background: rgba(98, 122, 153, 0.8);
}
.mega-menu {
	height: 100vh;
	position: fixed;
	width: 100%;
	z-index: 1002;
	top: 0;
	left: -101vw;
	transition: 400ms;
	background: black;
	overflow: hidden;
}
.mega-menu.active {
	left: 0;
}
.mega-menu-container,.mega-menu-column-content,.mega-menu-column {
	height: 100%;
}
.mega-menu-column {
	background: black;
	position: relative;
	padding:0 calc(1vw + 56px);
	padding-right: 1vw;
}
.mega-menu-column-content {
	display: flex;
	justify-content: center;
	align-items: center;
	position: relative;
}
.mega-menu-list {
	text-align: left

;
	width: 100%;
}
.mega-menu-list .mega-menu-list-item a {
	color:var(--gray);
	font-weight: 600;
	line-height: 1.3;
	transition: 300ms;
	cursor: pointer;
}
#ru .mega-menu-list .mega-menu-list-item a {
	font-weight: 500;
}
.mega-menu-list--first-column {
	max-width: 260px;
}
.mega-menu-list--second-column {
	max-width: 100%;
}
.mega-menu-list--second-column,.mega-menu-list--third-column {
	display: none;
}
.mega-menu-list.active {
	display: block;
}
.mega-menu-list--first-column a {
	font-size: 18px;
	text-transform: uppercase;
}
.mega-menu-list--second-column a,.mega-menu-list--third-column a:not(.mega-menu-btn) {
	font-size: 20px;
	/*max-width: 410px;*/
}
#ru .mega-menu-list--second-column a,#ru .mega-menu-list--third-column a:not(.mega-menu-btn) {
	font-size: 18px;
}
.mega-menu-list .mega-menu-list-item a:hover,.mega-menu-list .mega-menu-list-item.active > a {
	color:white;
}
.mega-menu-desktop .mega-menu-list--first-column .mega-menu-list-item.active > a {
	font-size: 32px;
	text-transform: capitalize;
}
.mega-menu-list .mega-menu-list-item:not(:first-child) {
	margin-top:32px
}
.mega-menu-list.mega-menu-list--third-column .mega-menu-list-item:not(:first-child) {
	margin-top:42px;
}
.mega-menu-column:not(.mega-menu-column--dark)::before {
	content:'';
	position: absolute;
	left:0;top:0;right:0;bottom:0;
	background: rgba(33,47,65,.6);
}
.mega-menu-column:not(.mega-menu-column--dark):not(:first-child)::after {
	content:'';
	position: absolute;
	left:0;
	height: 100%;
	top:0;
	border-left: 2px solid var(--gray-blue);
	opacity: .32;
}
#mega-menu-logo {
	position: absolute;
	top: 36px;
	left: 42px;
	width: 240px;
	max-width: 100%;
}
.mega-menu-header {
	font-size: 16px;
	font-style: normal;
	font-weight: 600;
